    }),
  });
  vi.mocked(flight.fetchFlightSequences).mockResolvedValue([
    { ...onAirLog(props()), isRunning: false, scheduledAt: null },
  ]);
  mount(liveProps());
  expect(await screen.findByText("Stream connected")).toBeVisible();
